const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const app=$('#app'),toastEl=$('#toast');
let config={brand:'NutriPilot',prices:{monthly:'9.90',quarterly:'19.90',yearly:'39.90'},trialDays:0,ai:false,checkoutConfigured:{},supportEmail:'support@atlasevermore.com',legal:{}};
const defaultState={onboarding:false,premium:false,premiumEmail:'',accessToken:'',profile:{name:'',sex:'female',age:32,height:165,weight:70,target:62,activity:1.375,goal:'lose',speed:.35,diet:'balanced',allergies:'',mealsPerDay:3,cooking:'15-30 min',challenge:'portions',dailyKcal:1700,protein:110,carbs:190,fat:55,fiber:25},meals:[],favorites:[],water:{},weights:[],waist:[],coach:[],planned:[],achievements:[],trialScans:0,utms:{},lastOpen:''};
let state=load(),route=location.hash.replace('#','')||(state.onboarding?'app':'home'),ob={step:0,data:{...state.profile}},modal=null,selectedPlan='quarterly';

function load(){try{return deepMerge(structuredClone(defaultState),JSON.parse(localStorage.getItem('nutripilot_v3')||'{}'))}catch{return structuredClone(defaultState)}}
function deepMerge(a,b){for(const k of Object.keys(b||{})){if(b[k]&&typeof b[k]==='object'&&!Array.isArray(b[k])&&a[k]&&typeof a[k]==='object')deepMerge(a[k],b[k]);else a[k]=b[k]}return a}
function save(){localStorage.setItem('nutripilot_v3',JSON.stringify(state))}
function nav(r){route=r;location.hash=r;render();scrollTo(0,0)}
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function clamp(n,a,b){return Math.max(a,Math.min(b,n))}
function fmt(n,d=0){return Number(n||0).toLocaleString('fr-FR',{maximumFractionDigits:d,minimumFractionDigits:d})}
function todayKey(d=new Date()){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function addDays(n){const d=new Date();d.setDate(d.getDate()+n);return todayKey(d)}
function dateLabel(k){return new Date(k+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}
function toast(s){toastEl.textContent=s;toastEl.classList.add('show');setTimeout(()=>toastEl.classList.remove('show'),2400)}
function track(name,params={}){window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:name,...params});try{window.fbq?.('trackCustom',name,params)}catch{}}
function logo(){return `<div class="logo"><span class="logo-mark"></span>${esc(config.brand)}</div>`}
function captureUtms(){const q=new URLSearchParams(location.search);for(const k of ['utm_source','utm_medium','utm_campaign','utm_content','utm_term'])if(q.get(k))state.utms[k]=q.get(k);if(q.get('paid')==='1')route='access';save()}
function totals(day=todayKey()){return state.meals.filter(m=>m.day===day).reduce((a,m)=>({kcal:a.kcal+Number(m.total?.kcal||0),protein:a.protein+Number(m.total?.protein||0),carbs:a.carbs+Number(m.total?.carbs||0),fat:a.fat+Number(m.total?.fat||0),fiber:a.fiber+Number(m.total?.fiber||0)}),{kcal:0,protein:0,carbs:0,fat:0,fiber:0})}
function waterToday(){return Number(state.water[todayKey()]||0)}
function daysLogged(){return new Set(state.meals.map(m=>m.day)).size}
function streak(){let s=0;for(let i=0;i<365;i++){const k=addDays(-i);if(state.meals.some(m=>m.day===k))s++;else if(i===0)continue;else break}return s}
function scoreDay(day=todayKey()){const t=totals(day),p=state.profile;if(!t.kcal)return 0;const kcal=Math.max(0,100-Math.abs(t.kcal-p.dailyKcal)/p.dailyKcal*100);const pro=Math.min(100,t.protein/p.protein*100),fib=Math.min(100,t.fiber/p.fiber*100);return Math.round(kcal*.5+pro*.3+fib*.2)}

async function init(){captureUtms();try{const r=await fetch('/api/config');if(r.ok)config={...config,...await r.json()}}catch{}if(state.premium&&state.accessToken){try{const r=await fetch('/api/access/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:state.accessToken})});const d=await r.json();if(!r.ok||!d.premium){state.premium=false;state.accessToken='';save()}}catch{}}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})}
window.addEventListener('hashchange',()=>{route=location.hash.replace('#','')||'home';render()});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();window.deferredInstall=e});

function home(){return `<div class="app-root"><div class="container"><header class="topbar">${logo()}<div class="top-actions"><button class="btn btn-ghost" data-go="access">J’ai déjà acheté</button><button class="btn btn-primary" data-start>Créer mon plan</button></div></header><main class="hero"><div><span class="tag">NUTRITION SIMPLE • FRANCE</span><h1>Votre nutrition, <em>enfin claire.</em></h1><p>Photographiez un repas, corrigez les portions en quelques secondes, suivez vos macros et laissez ${esc(config.brand)} vous proposer quoi manger ensuite selon votre journée.</p><div class="cta-row"><button class="btn btn-lime" data-start>Créer mon plan personnalisé →</button><button class="btn btn-ghost" data-go="premium">Voir Premium</button></div><div class="microproof"><span>✓ Photo + texte + code-barres</span><span>✓ Portions modifiables</span><span>✓ Planification intelligente</span><span>✓ PWA installable</span></div></div><div class="stage"><div class="phone"><div class="phone-notch"></div><div class="phone-inner"><div class="mock-top"><b>Bonjour 👋</b><span class="pill">🔥 8 jours</span></div><div class="mock-ring"><div><strong>1 284</strong><small>/ 1 750 kcal</small></div></div><div class="mock-grid"><div class="mock-card">🥚<b>Protéines</b><small>76 / 110 g</small></div><div class="mock-card">🌾<b>Fibres</b><small>19 / 25 g</small></div></div><div class="mock-scan"><div><small>Analyse en quelques secondes</small><br><b>📸 Scanner mon repas</b></div><b>→</b></div></div></div><div class="float a">✨ Quoi manger ensuite ?</div><div class="float b">🎯 Fourchette calorique<br>440–520 kcal</div><div class="float c">✓ Portions corrigibles</div></div></main></div><section class="section"><div class="container"><span class="tag">PLUS QU’UN COMPTEUR</span><h2>Le problème n’est pas de compter.<br>C’est de savoir quoi faire ensuite.</h2><p class="lead">Nous gardons ce qui marche dans les meilleurs trackers — calories, macros, photo, code-barres — puis nous ajoutons la couche qui manque : décision, correction et planification.</p><div class="grid3">${feature('📸','Photo avec incertitude','Une estimation + une fourchette réaliste et des grammes modifiables, au lieu d’un chiffre présenté comme exact.',true)}${feature('✨','Composer mon repas','Calories restantes + envie + préférences → trois options concrètes adaptées à la journée.')}${feature('💬','Coach nutritionnel','Posez une question simple et obtenez une réponse contextualisée à vos objectifs et à ce que vous avez déjà mangé.')}${feature('▤','Code-barres','Produits emballés via Open Food Facts, quantité modifiable avant enregistrement.')}${feature('♡','Favoris & routines','Enregistrez petit-déjeuner, café, bowl ou repas récurrent en un geste.')}${feature('↗','Progression utile','Poids, tour de taille, tendances hebdomadaires, score de régularité et hydratation.')}</div><div class="compare"><div class="compare-row"><b>Fonction</b><b>Tracker classique</b><b>${esc(config.brand)}</b></div>${[['Calories & macros','✓','✓'],['Photo du repas','✓','✓'],['Code-barres','✓','✓'],['Fourchette d’incertitude','—','✓'],['Correction de portions avec recalcul','Variable','✓'],['Quoi manger ensuite','—','✓'],['Coach contextualisé','Variable','✓'],['Hydratation & progression','Variable','✓'],['Favoris / routines','Variable','✓']].map(r=>`<div class="compare-row"><span>${r[0]}</span><b>${r[1]}</b><b>${r[2]}</b></div>`).join('')}</div></div></section><footer class="footer"><div class="container footer-row"><span>${esc(config.brand)} • outil de suivi général, pas un dispositif médical.</span><span>© 2026 • France</span></div></footer></div>`}
function feature(i,t,p,hero=false){return `<article class="feature ${hero?'hero-feature':''}"><span class="ico">${i}</span><h3>${t}</h3><p>${p}</p></article>`}

const obSteps=[
 {key:'goal',title:'Quel est votre objectif principal ?',sub:'Nous adaptons le point de départ. Vous pourrez le modifier.',type:'options',opts:[['lose','Perdre du poids','Progressivement'],['maintain','Maintenir mon poids','Stabilité'],['gain','Prendre du muscle','Surplus modéré']]},
 {key:'sex',title:'Quel sexe utiliser pour le calcul énergétique ?',sub:'La formule Mifflin–St Jeor utilise ce paramètre biologique.',type:'options',opts:[['female','Femme','Formule femme'],['male','Homme','Formule homme'],['other','Autre / préfère ne pas dire','Estimation intermédiaire']]},
 {key:'age',title:'Quel âge avez-vous ?',sub:'Cette version est réservée aux adultes.',type:'number',min:18,max:90,unit:'ans'},
 {key:'height',title:'Quelle est votre taille ?',sub:'En centimètres.',type:'number',min:130,max:220,unit:'cm'},
 {key:'weight',title:'Quel est votre poids actuel ?',sub:'Une estimation suffit pour commencer.',type:'number',min:35,max:250,step:.1,unit:'kg'},
 {key:'target',title:'Quel poids souhaitez-vous atteindre ?',sub:'Nous éviterons les objectifs manifestement incohérents.',type:'number',min:35,max:250,step:.1,unit:'kg'},
 {key:'activity',title:'À quoi ressemble votre activité ?',sub:'Choisissez l’option la plus proche de votre semaine réelle.',type:'options',opts:[[1.2,'Plutôt sédentaire','Peu d’activité'],[1.375,'Légèrement actif','1–3 séances/semaine'],[1.55,'Actif','3–5 séances/semaine'],[1.725,'Très actif','6–7 séances/semaine']]},
 {key:'speed',title:'Quel rythme vous semble durable ?',sub:'Nous plafonnons automatiquement les ajustements agressifs.',type:'options',opts:[[.2,'Très progressif','≈ 0,2 kg/semaine'],[.35,'Progressif','≈ 0,35 kg/semaine'],[.5,'Soutenu','≈ 0,5 kg/semaine']]},
 {key:'diet',title:'Quel style alimentaire vous convient ?',sub:'Pas de règle rigide — seulement des préférences pour les suggestions.',type:'options',opts:[['balanced','Équilibré','Aucune restriction'],['highprotein','Riche en protéines','Priorité aux protéines'],['vegetarian','Végétarien','Sans viande/poisson'],['vegan','Vegan','Sans produits animaux'],['lowcarb','Modéré en glucides','Moins de glucides']]},
 {key:'allergies',title:'Y a-t-il des aliments à éviter ?',sub:'Allergies, intolérances ou préférences. Vous pouvez laisser vide.',type:'text',placeholder:'Ex. arachides, lactose…'},
 {key:'mealsPerDay',title:'Combien de repas vous conviennent ?',sub:'Le planificateur utilisera ce rythme.',type:'options',opts:[[2,'2 repas','Simple'],[3,'3 repas','Classique'],[4,'4 repas','Avec collation']]},
 {key:'cooking',title:'Combien de temps voulez-vous cuisiner ?',sub:'Nous adapterons les idées de repas.',type:'options',opts:[['<15 min','Moins de 15 min','Très rapide'],['15-30 min','15 à 30 min','Standard'],['30+ min','30 min ou plus','J’aime cuisiner']]},
 {key:'challenge',title:'Qu’est-ce qui vous bloque le plus ?',sub:'Cela personnalise les conseils du tableau de bord.',type:'options',opts:[['portions','Les portions','Je ne sais pas combien manger'],['ideas','Les idées de repas','Je manque d’inspiration'],['consistency','La régularité','Je commence puis j’abandonne'],['protein','Les protéines','J’ai du mal à atteindre mon objectif']]},
 {key:'name',title:'Comment devons-nous vous appeler ?',sub:'Dernière étape.',type:'text',placeholder:'Votre prénom'}
];
function onboarding(){const s=obSteps[ob.step],pct=((ob.step+1)/obSteps.length)*100;return `<div class="onboard"><aside class="onboard-art">${logo()}<div><span class="tag">PLAN PERSONNALISÉ</span><h2>Moins de saisie.<br>Plus de décisions utiles.</h2></div><div class="quote-card"><b>Conçu pour être corrigible.</b><p style="color:#d5e0d7;line-height:1.5;margin-bottom:0">Une photo n’est jamais une balance. ${esc(config.brand)} affiche donc une estimation, une fourchette et vous laisse corriger les portions.</p></div></aside><main class="onboard-main"><div>${logo()}<div class="progress-steps"><i style="width:${pct}%"></i></div></div><div class="question"><small>ÉTAPE ${ob.step+1} / ${obSteps.length}</small><h1>${s.title}</h1><p>${s.sub}</p>${obInput(s)}</div><div class="nextbar"><button class="back" data-ob-back ${ob.step===0?'style="visibility:hidden"':''}>← Retour</button><button class="btn btn-primary" data-ob-next>${ob.step===obSteps.length-1?'Créer mon plan':'Continuer →'}</button></div></main></div>`}
function obInput(s){const v=ob.data[s.key]??'';if(s.type==='options')return `<div class="options">${s.opts.map(o=>`<button class="option ${String(o[0])===String(v)?'selected':''}" data-ob-value="${o[0]}"><span>${o[1]}</span><b>${o[2]}</b></button>`).join('')}</div>`;if(s.type==='number')return `<div style="display:flex;gap:10px;align-items:end;margin-top:30px"><input class="input-big" id="ob-field" type="number" min="${s.min}" max="${s.max}" step="${s.step||1}" value="${esc(v)}"><span class="unit">${s.unit}</span></div>`;return `<input class="input-big" id="ob-field" type="text" placeholder="${s.placeholder||''}" value="${esc(v)}" style="font-size:34px;margin-top:30px;max-width:100%">`}
function calcPlan(){const p={...ob.data};const age=Number(p.age),w=Number(p.weight),h=Number(p.height);let base=10*w+6.25*h-5*age;let bmr=base+(p.sex==='male'?5:p.sex==='female'?-161:-78);let tdee=bmr*Number(p.activity||1.375);let kcal=tdee;if(p.goal==='lose'){const desired=Number(p.speed||.35)*7700/7;const safeDef=Math.min(desired,tdee*.2);kcal=tdee-safeDef}if(p.goal==='gain')kcal=tdee+Math.min(300,tdee*.12);kcal=Math.round(kcal/10)*10;const bmi=w/((h/100)**2);let warning='';if(age<18)warning='Cette version ne prend pas en charge les mineurs.';if(p.goal==='lose'&&bmi<18.5){kcal=Math.round(tdee/10)*10;warning='Votre objectif de perte de poids nécessite un avis professionnel avant de créer un déficit.'}const protein=Math.round(w*(p.goal==='gain'?1.8:1.6));const fat=Math.round(w*.8);const carbs=Math.max(80,Math.round((kcal-protein*4-fat*9)/4));const fiber=Math.max(25,Math.round(kcal/1000*14));return {...p,bmr:Math.round(bmr),tdee:Math.round(tdee),bmi:+bmi.toFixed(1),dailyKcal:kcal,protein,carbs,fat,fiber,warning}}
function planScreen(){const p=calcPlan();return `<div class="mobile-app"><div class="app-head"><div class="app-head-row">${logo()}<span class="pill">Plan prêt ✓</span></div></div><div class="screen"><div style="text-align:center;padding:24px 0"><span class="tag">VOTRE POINT DE DÉPART</span><h1 class="screen-title">${esc(p.name||'Votre plan')}, c’est prêt.</h1><p class="screen-sub">Un budget quotidien modifiable, pas une prescription.</p></div><div class="today-card"><small>Objectif énergétique estimé</small><div style="font-size:56px;font-weight:950;letter-spacing:-.06em;margin:8px 0">${fmt(p.dailyKcal)} <span style="font-size:16px">kcal</span></div><div class="small-stats"><div class="small-stat"><span>Protéines</span><b>${p.protein} g</b></div><div class="small-stat"><span>Glucides</span><b>${p.carbs} g</b></div><div class="small-stat"><span>Lipides</span><b>${p.fat} g</b></div><div class="small-stat"><span>Fibres</span><b>${p.fiber} g</b></div></div></div>${p.warning?`<div class="warn"><b>Attention.</b><br>${esc(p.warning)}</div>`:`<div class="warn"><b>Estimation générale.</b><br>Les besoins réels varient selon santé, grossesse, médicaments, historique alimentaire et autres facteurs. En cas de situation médicale, demandez un avis professionnel.</div>`}<button class="btn btn-lime btn-wide" style="margin-top:14px" data-activate>Ouvrir mon espace →</button><button class="btn btn-ghost btn-wide" style="margin-top:8px" data-go="premium">Découvrir Premium</button></div></div>`}

function appHeader(title){return `<div class="app-head"><div class="app-head-row"><div><small style="color:var(--muted);font-weight:900">${new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}</small><h2 style="margin:3px 0 0;font-size:25px;letter-spacing:-.04em">${title}</h2></div><button class="icon-btn" data-go="settings">⚙</button></div></div>`}
function bottom(active){const tabs=[['app','⌂','Aujourd’hui'],['insights','◷','Analyse'],['add','＋','Ajouter'],['planner','✦','Planifier'],['progress','↗','Progrès']];return `<nav class="bottom-nav">${tabs.map(([r,i,l])=>`<button class="nav-btn ${r===active?'active':''} ${r==='add'?'center':''}" ${r==='add'?'data-open-add':'data-go="'+r+'"'}><span>${i}</span>${l}</button>`).join('')}</nav>`}
function macroStat(name,val,target){const pct=clamp(val/target*100,0,100);return `<div><div class="small-stat"><span>${name}</span><b>${fmt(val,1)} / ${target} g</b></div><div class="progress"><i style="width:${pct}%"></i></div></div>`}
function dashboard(){const t=totals(),p=state.profile,left=Math.max(0,p.dailyKcal-t.kcal),pct=clamp(t.kcal/p.dailyKcal*100,0,100),w=waterToday();return `<div class="mobile-app">${appHeader(`Bonjour ${esc(p.name||'')} 👋`)}<div class="screen"><div style="display:flex;justify-content:space-between;align-items:center;margin:4px 2px 10px"><span class="streak">🔥 ${streak()} jour${streak()>1?'s':''}</span><span class="pill">Score ${scoreDay()}/100</span></div><div class="today-card"><div class="today-top"><b>Aujourd’hui</b><button class="pill" style="background:#2e4335;color:white;border:0" data-go="${state.premium?'settings':'premium'}">${state.premium?'Premium ✓':'Passer Premium'}</button></div><div class="today-main"><div class="big-ring" style="--p:${pct}%"><div><strong>${fmt(t.kcal)}</strong><small>/ ${fmt(p.dailyKcal)} kcal</small></div></div><div class="small-stats">${macroStat('Protéines',t.protein,p.protein)}${macroStat('Glucides',t.carbs,p.carbs)}${macroStat('Lipides',t.fat,p.fat)}${macroStat('Fibres',t.fiber,p.fiber)}</div></div><div style="margin-top:14px;color:#dbe5de"><b>${fmt(left)} kcal restantes</b> selon votre objectif actuel.</div></div><div class="action-grid"><button class="action-card primary" data-add-tab="photo"><span class="aico">📸</span><b>Scanner mon repas</b></button><button class="action-card" data-go="planner"><span class="aico">✨</span><b>Quoi manger ensuite ?</b></button><button class="action-card" data-go="coach"><span class="aico">💬</span><b>Demander au coach</b></button><button class="action-card" data-add-tab="barcode"><span class="aico">▤</span><b>Code-barres</b></button></div><div class="section-label"><h3>Hydratation</h3><span class="fine">objectif indicatif 2 L</span></div><div class="water-card"><div class="water-row"><div><b>💧 ${fmt(w)} ml</b><div class="fine">Aujourd’hui</div></div><div class="water-actions"><button data-water="250">+250</button><button data-water="500">+500</button></div></div><div class="mini-bar"><i style="width:${clamp(w/2000*100,0,100)}%"></i></div></div><div class="section-label"><h3>Mes repas</h3><button class="link-btn" data-open-add>＋ Ajouter</button></div>${mealsHtml(state.meals.filter(m=>m.day===todayKey()))}<div class="section-label"><h3>Prochaine décision</h3></div>${insight(t,p)}</div>${bottom('app')}</div>`}
function mealsHtml(ms){if(!ms.length)return `<div class="empty">Aucun repas enregistré aujourd’hui.<br><b>Photo, texte, code-barres ou favori : choisissez le plus rapide.</b></div>`;return `<div class="meal-list">${ms.slice().reverse().map(m=>`<button class="meal" data-meal="${m.id}" style="width:100%;text-align:left"><div class="meal-ico">${m.icon||'🍽️'}</div><div><b>${esc(m.title)}</b><small>${m.foods?.length||1} élément(s) • ${fmt(m.total.protein,1)} g protéines</small></div><b>${fmt(m.total.kcal)} kcal</b></button>`).join('')}</div>`}
function insight(t,p){if(!t.kcal)return `<div class="insight"><strong>Commencez par le prochain repas.</strong>Une photo suffit. Corrigez les quantités si nécessaire avant de l’enregistrer.</div>`;if(t.protein<p.protein*.55&&t.kcal>p.dailyKcal*.55)return `<div class="insight"><strong>Priorité protéines.</strong>Votre journée est déjà avancée en calories mais reste basse en protéines. « Planifier » peut proposer un repas plus riche en protéines.</div>`;if(t.fiber<p.fiber*.45&&t.kcal>p.dailyKcal*.55)return `<div class="insight"><strong>Les fibres sont en retard.</strong>Un repas avec légumes, légumineuses, fruits ou céréales complètes peut aider.</div>`;return `<div class="insight"><strong>Trajectoire cohérente.</strong>Utilisez « Quoi manger ensuite ? » pour transformer vos calories restantes en options concrètes.</div>`}

function openAdd(tab='photo'){modal={type:'add',tab,result:null,image:'',loading:false};renderModal()}
function renderModal(){document.querySelector('.modal-wrap')?.remove();if(!modal)return;const w=document.createElement('div');w.className='modal-wrap';w.innerHTML=`<div class="sheet"><div class="sheet-grip"></div>${modal.type==='add'?addSheet():mealSheet(modal.meal)}</div>`;document.body.appendChild(w);bindModal(w)}
function addSheet(){if(modal.loading)return `<div class="loader"><div class="loader-dots"><i></i><i></i><i></i></div><h3>Analyse en cours…</h3><p class="screen-sub">Nous estimons les aliments et les portions. Vous pourrez tout corriger.</p></div>`;if(modal.result)return resultSheet(modal.result);const tabs=[['photo','📸 Photo'],['text','✍️ Texte'],['barcode','▤ Code-barres'],['label','🏷 Étiquette'],['manual','🔎 Manuel'],['favorites','♡ Favoris']];return `<div class="sheet-head"><div><h2 style="margin:0">Ajouter un repas</h2><div class="fine">Choisissez le moyen le plus rapide.</div></div><button class="icon-btn" data-close>×</button></div><div class="tabs">${tabs.map(([k,l])=>`<button class="tab ${modal.tab===k?'active':''}" data-mtab="${k}">${l}</button>`).join('')}</div>${addTab(modal.tab)}`}
function addTab(tab){if(tab==='photo'||tab==='label')return `<label class="upload"><input id="meal-image" type="file" accept="image/*" capture="environment"><div class="camera-ico">${tab==='photo'?'📸':'🏷'}</div><h3>${tab==='photo'?'Photographier le repas':'Photographier l’étiquette'}</h3><p class="screen-sub">${tab==='photo'?'Cadrez le repas entier, avec les accompagnements visibles.':'Cadrez la table nutritionnelle et les portions.'}</p><span class="btn btn-primary">Choisir une photo</span></label>${!config.ai?`<div class="warn"><b>Mode démo.</b> L’analyse visuelle réelle nécessite la configuration IA côté serveur. Le reste de l’application fonctionne.</div>`:''}`;if(tab==='text')return `<textarea class="textarea" id="meal-text" placeholder="Ex. 2 œufs, 80 g de pain complet, 1/2 avocat…"></textarea><div style="display:flex;gap:8px;margin-top:9px"><button class="voice-btn" data-voice>🎙 Dicter</button><button class="btn btn-primary" style="flex:1" data-analyze-text>Analyser →</button></div>`;if(tab==='barcode')return `<div class="field"><label>Code EAN / UPC</label><input id="barcode" inputmode="numeric" placeholder="Ex. 3017620422003"></div><button class="btn btn-primary btn-wide" style="margin-top:10px" data-barcode>Rechercher le produit →</button><div class="fine" style="margin-top:10px">Données produit via Open Food Facts. Vérifiez toujours l’étiquette du produit que vous consommez.</div>`;if(tab==='manual')return `<div class="field"><label>Rechercher un aliment courant</label><input id="manual-search" placeholder="Poulet, riz, skyr…"></div><div class="manual-list" id="manual-list"></div>`;if(tab==='favorites')return state.favorites.length?`<div class="manual-list">${state.favorites.map((f,i)=>`<button class="manual-item" data-fav="${i}"><span><b>${esc(f.title)}</b><small style="display:block;color:var(--muted)">${fmt(f.total.kcal)} kcal</small></span><b>＋</b></button>`).join('')}</div>`:`<div class="empty" style="margin-top:14px">Vous n’avez pas encore de favori.<br>Enregistrez un repas analysé puis ajoutez-le aux favoris.</div>`;return''}
const localFood=[['Œuf',143,12.6,.7,9.5,0],['Pain complet',247,13,41,4.2,7],['Avocat',160,2,8.5,14.7,6.7],['Poulet grillé',165,31,0,3.6,0],['Riz cuit',130,2.7,28,.3,.4],['Pâtes cuites',158,5.8,31,.9,1.8],['Saumon',208,20,0,13,0],['Thon au naturel',116,26,0,1,0],['Skyr',63,11,4,.2,0],['Banane',89,1.1,23,.3,2.6],['Pomme',52,.3,14,.2,2.4],['Lentilles cuites',116,9,20,.4,8],['Quinoa cuit',120,4.4,21,1.9,2.8],['Brocoli',35,2.4,7.2,.4,3.3],['Flocons d’avoine',389,16.9,66.3,6.9,10.6],['Amandes',579,21,22,50,12.5],['Baguette',270,9,57,1,2.7],['Croissant',406,8,46,21,2.6]];
function manualResults(q=''){q=q.trim().toLowerCase();return localFood.filter(x=>!q||x[0].toLowerCase().includes(q)).slice(0,10).map((f,i)=>`<button class="manual-item" data-manual="${esc(JSON.stringify(f))}"><span><b>${f[0]}</b><small style="display:block;color:var(--muted)">${f[1]} kcal / 100 g</small></span><b>＋</b></button>`).join('')}
function resultSheet(r){const range=r.range||{min:Math.round(r.total.kcal*.9),max:Math.round(r.total.kcal*1.1)};return `<div class="sheet-head"><div><span class="confidence">${Math.round((r.confidence||.5)*100)}% confiance</span><h2 style="margin:8px 0 0">${esc(r.title||'Repas')}</h2></div><button class="icon-btn" data-close>×</button></div>${r.image?`<img class="preview" src="${esc(r.image)}" alt="Produit">`:''}<div class="result-total"><div class="range">Fourchette estimée ${fmt(range.min)}–${fmt(range.max)} kcal</div><strong id="total-kcal">${fmt(r.total.kcal)}</strong> kcal<div class="nutrition-line" style="margin-top:12px"><div><b id="total-p">${fmt(r.total.protein,1)}</b>prot.</div><div><b id="total-c">${fmt(r.total.carbs,1)}</b>gluc.</div><div><b id="total-f">${fmt(r.total.fat,1)}</b>lip.</div><div><b id="total-fi">${fmt(r.total.fiber,1)}</b>fibres</div></div></div><div id="foods-edit">${r.foods.map((f,i)=>foodEdit(f,i)).join('')}</div>${(r.assumptions||[]).length?`<div class="warn"><b>À confirmer :</b><br>${r.assumptions.map(x=>'• '+esc(x)).join('<br>')}</div>`:''}<div class="fine" style="margin-top:10px">${esc(r.note||'Les valeurs sont des estimations générales.')}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:13px"><button class="btn btn-ghost" data-save-favorite>♡ Favori</button><button class="btn btn-lime" data-save-result>Ajouter au journal</button></div>`}
function foodEdit(f,i){const g=Number(f.grams||100);return `<div class="food-edit" data-fi="${i}" data-baseg="${g}" data-k="${Number(f.kcal||0)}" data-p="${Number(f.protein||0)}" data-c="${Number(f.carbs||0)}" data-f="${Number(f.fat||0)}" data-fiber="${Number(f.fiber||0)}"><div class="food-edit-top"><div><b>${esc(f.name)}</b><div class="fine">${fmt(f.kcal)} kcal estimées</div></div><label><input data-grams type="number" min="1" max="2000" value="${g}"> g</label></div><div class="food-macros"><span class="chip">P ${fmt(f.protein,1)} g</span><span class="chip">G ${fmt(f.carbs,1)} g</span><span class="chip">L ${fmt(f.fat,1)} g</span><span class="chip">Fibres ${fmt(f.fiber,1)} g</span></div></div>`}
function recalcResult(root){const r=modal.result;let T={kcal:0,protein:0,carbs:0,fat:0,fiber:0};$$('[data-fi]',root).forEach(el=>{const i=Number(el.dataset.fi),base=Number(el.dataset.baseg)||100,g=Math.max(1,Number($('[data-grams]',el).value)||base),q=g/base;const f=r.foods[i];f.grams=g;for(const [key,d] of [['kcal','k'],['protein','p'],['carbs','c'],['fat','f'],['fiber','fiber']]){f[key]=+(Number(el.dataset[d])*q).toFixed(key==='kcal'?0:1);T[key]+=f[key]}});T.kcal=Math.round(T.kcal);for(const k of ['protein','carbs','fat','fiber'])T[k]=+T[k].toFixed(1);r.total=T;$('#total-kcal',root).textContent=fmt(T.kcal);$('#total-p',root).textContent=fmt(T.protein,1);$('#total-c',root).textContent=fmt(T.carbs,1);$('#total-f',root).textContent=fmt(T.fat,1);$('#total-fi',root).textContent=fmt(T.fiber,1)}
function mealSheet(m){return `<div class="sheet-head"><div><h2 style="margin:0">${esc(m.title)}</h2><div class="fine">${dateLabel(m.day)}</div></div><button class="icon-btn" data-close>×</button></div><div class="result-total"><strong>${fmt(m.total.kcal)}</strong> kcal<div class="nutrition-line" style="margin-top:12px"><div><b>${fmt(m.total.protein,1)}</b>prot.</div><div><b>${fmt(m.total.carbs,1)}</b>gluc.</div><div><b>${fmt(m.total.fat,1)}</b>lip.</div><div><b>${fmt(m.total.fiber,1)}</b>fibres</div></div></div><div class="manual-list">${(m.foods||[]).map(f=>`<div class="manual-item"><span><b>${esc(f.name)}</b><small style="display:block;color:var(--muted)">${fmt(f.grams||0)} g</small></span><span>${fmt(f.kcal||0)} kcal</span></div>`).join('')}</div><button class="btn btn-ghost btn-wide" style="margin-top:12px;color:var(--danger)" data-delete-meal="${m.id}">Supprimer ce repas</button>`}

function planner(){const t=totals(),p=state.profile,left=Math.max(180,p.dailyKcal-t.kcal);return `<div class="mobile-app">${appHeader('Planifier')}<div class="screen"><h1 class="screen-title">Quoi manger ensuite ?</h1><p class="screen-sub">Transformez ce qu’il vous reste aujourd’hui en options concrètes.</p><div class="compose-card"><small>Budget restant estimé</small><div class="compose-number">${fmt(left)} kcal</div><div class="fine" style="color:#40512d">P ${Math.max(0,Math.round(p.protein-t.protein))} g restantes • Fibres ${Math.max(0,Math.round(p.fiber-t.fiber))} g restantes</div></div><div class="field"><label>Une envie particulière ?</label><input id="craving" placeholder="Ex. pâtes, pizza, quelque chose de frais…"></div><div class="field"><label>Style</label><select id="preference"><option value="${esc(p.diet)}">Ma préférence habituelle</option><option>riche en protéines</option><option>rapide</option><option>végétarien</option><option>léger</option></select></div><button class="btn btn-primary btn-wide" style="margin-top:12px" data-compose data-remaining="${left}">Générer 3 options →</button><div id="compose-results"></div><div class="section-label"><h3>Planifier demain</h3></div><div class="insight"><strong>Astuce anti-friction.</strong>Ajoutez dès aujourd’hui un petit-déjeuner ou déjeuner récurrent aux favoris : demain, vous le journaliserez en un geste.</div></div>${bottom('planner')}</div>`}
async function doCompose(btn){const box=$('#compose-results');box.innerHTML=`<div class="loader"><div class="loader-dots"><i></i><i></i><i></i></div>Création des options…</div>`;try{const b={remaining:Number(btn.dataset.remaining),craving:$('#craving').value,preference:$('#preference').value,avoid:state.profile.allergies,cooking:state.profile.cooking};const r=await fetch('/api/compose',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),d=await r.json();if(!r.ok)throw new Error(d.error);box.innerHTML=d.options.map(s=>`<article class="suggestion"><h3>${esc(s.name)}</h3><p class="screen-sub" style="margin:0">${esc(s.why||'')}</p><div class="ingredients">${(s.ingredients||[]).map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><div class="nutrition-line"><div><b>${fmt(s.kcal)}</b>kcal</div><div><b>${fmt(s.protein)}</b>prot.</div><div><b>${fmt(s.carbs)}</b>gluc.</div><div><b>${fmt(s.fiber)}</b>fibres</div></div><div class="fine" style="margin-top:8px">⏱ ${esc(s.prep||state.profile.cooking)}</div><button class="btn btn-ghost btn-wide" style="margin-top:10px" data-add-suggestion='${esc(JSON.stringify(s))}'>Ajouter au journal</button></article>`).join('');track('MealComposerUsed')}catch(e){box.innerHTML=`<div class="warn">${esc(e.message)}</div>`}}

function coach(){const t=totals(),p=state.profile;return `<div class="mobile-app">${appHeader('Coach')}<div class="screen"><h1 class="screen-title">Demandez simplement.</h1><p class="screen-sub">« Je veux manger une pizza ce soir », « comment augmenter mes protéines ? », « que faire avec 500 kcal restantes ? »</p><div class="chat" id="chat">${state.coach.length?state.coach.slice(-12).map(m=>`<div class="bubble ${m.role==='user'?'user':'ai'}">${esc(m.text)}</div>`).join(''):`<div class="bubble ai">Bonjour ${esc(p.name||'')} 👋 Je peux vous aider à transformer votre journée en décisions simples, sans culpabilité.</div>`}</div><div class="chatbar"><input id="coach-input" placeholder="Posez votre question…"><button class="btn btn-primary" data-coach-send>→</button></div><div class="fine">Conseils généraux uniquement. Pour une situation médicale, grossesse, trouble alimentaire ou traitement, consultez un professionnel de santé.</div></div>${bottom('')}</div>`}
async function sendCoach(){const input=$('#coach-input'),msg=input.value.trim();if(!msg)return;state.coach.push({role:'user',text:msg});save();render();try{const t=totals(),p=state.profile,r=await fetch('/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:msg,goal:p.goal,dailyKcal:p.dailyKcal,remaining:Math.max(0,p.dailyKcal-t.kcal),proteinLeft:Math.max(0,p.protein-t.protein),diet:p.diet,allergies:p.allergies})}),d=await r.json();if(!r.ok)throw new Error(d.error);state.coach.push({role:'assistant',text:d.answer});save();render()}catch(e){state.coach.push({role:'assistant',text:'Je n’ai pas pu répondre pour le moment. '+e.message});save();render()}}

function insights(){const days=[...Array(7)].map((_,i)=>addDays(i-6)),p=state.profile;const data=days.map(day=>({day,...totals(day),water:Number(state.water[day]||0)}));const logged=data.filter(x=>x.kcal>0);const avg=logged.length?Math.round(logged.reduce((a,x)=>a+x.kcal,0)/logged.length):0,avgP=logged.length?Math.round(logged.reduce((a,x)=>a+x.protein,0)/logged.length):0;return `<div class="mobile-app">${appHeader('Analyse')}<div class="screen"><h1 class="screen-title">Votre semaine</h1><p class="screen-sub">La régularité compte plus qu’une journée parfaite.</p><div class="kpi-grid"><div class="kpi"><small>Moyenne</small><b>${fmt(avg)} kcal</b></div><div class="kpi"><small>Protéines moy.</small><b>${fmt(avgP)} g</b></div><div class="kpi"><small>Jours suivis</small><b>${logged.length}/7</b></div><div class="kpi"><small>Série actuelle</small><b>${streak()} j</b></div></div><div class="section-label"><h3>7 derniers jours</h3></div>${data.map(d=>`<div class="day-card"><div class="day-top"><div><b>${dateLabel(d.day)}</b><div class="fine">${fmt(d.protein,0)} g protéines • ${fmt(d.fiber,0)} g fibres</div></div><b>${fmt(d.kcal)} kcal</b></div><div class="mini-bar"><i style="width:${clamp(d.kcal/p.dailyKcal*100,0,100)}%"></i></div></div>`).join('')}<div class="section-label"><h3>Ce qui compte cette semaine</h3></div>${weeklyInsight(data,p)}<div class="section-label"><h3>Badges</h3></div>${achievements()}</div>${bottom('insights')}</div>`}
function weeklyInsight(data,p){const logged=data.filter(x=>x.kcal);if(logged.length<2)return `<div class="insight"><strong>Accumulez 2–3 jours.</strong>Nous pourrons alors distinguer une tendance d’une journée isolée.</div>`;const pro=logged.filter(x=>x.protein>=p.protein*.8).length,fib=logged.filter(x=>x.fiber>=p.fiber*.8).length;return `<div class="insight"><strong>Votre levier actuel : ${pro<logged.length/2?'protéines':fib<logged.length/2?'fibres':'régularité'}.</strong>${pro<logged.length/2?'Sur plusieurs jours, votre objectif protéique est rarement approché. Utilisez le planificateur avec « riche en protéines ».':fib<logged.length/2?'Ajoutez une source de fibres à un repas récurrent plutôt que de tout changer.':'Votre structure est cohérente. Cherchez la répétabilité plutôt que davantage de restriction.'}</div>`}
function achievements(){const vals=[['🥇','Premier repas',state.meals.length>=1],['📸','Premier scan',state.trialScans>=1],['🔥','Série 3 jours',streak()>=3],['🏆','Série 7 jours',streak()>=7],['💧','2 L en un jour',Object.values(state.water).some(v=>v>=2000)],['⚡','10 repas',state.meals.length>=10]];return `<div class="achievement-grid">${vals.map(v=>`<div class="achievement ${v[2]?'':'locked'}"><span>${v[0]}</span><div class="fine"><b>${v[1]}</b></div></div>`).join('')}</div>`}

function progress(){if(!state.weights.length)state.weights=[{day:todayKey(),value:Number(state.profile.weight)}];const vals=state.weights.slice(-12),pts=chartPoints(vals),start=vals[0]?.value||0,end=vals.at(-1)?.value||0;return `<div class="mobile-app">${appHeader('Progression')}<div class="screen"><h1 class="screen-title">Voir la tendance.</h1><p class="screen-sub">Le poids varie naturellement d’un jour à l’autre. Regardez surtout la trajectoire.</p><div class="chart"><svg viewBox="0 0 340 180" preserveAspectRatio="none"><path d="${pts.map((p,i)=>(i?'L':'M')+p.x+' '+p.y).join(' ')}"></path>${pts.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="5"></circle>`).join('')}</svg></div><div class="kpi-grid" style="margin-top:10px"><div class="kpi"><small>Évolution enregistrée</small><b>${end-start>0?'+':''}${fmt(end-start,1)} kg</b></div><div class="kpi"><small>Objectif déclaré</small><b>${fmt(state.profile.target,1)} kg</b></div></div><div class="field"><label>Poids aujourd’hui</label><input id="weight-now" type="number" step=".1" min="30" max="300" value="${state.profile.weight}"></div><div class="field"><label>Tour de taille (optionnel)</label><input id="waist-now" type="number" step=".1" min="40" max="200" placeholder="cm"></div><button class="btn btn-primary btn-wide" style="margin-top:10px" data-save-progress>Enregistrer</button><div class="section-label"><h3>Votre progression n’est pas un verdict</h3></div><div class="insight"><strong>Évitez de sur-réagir à une mesure isolée.</strong>Eau, sel, cycle, digestion et horaires peuvent déplacer le poids sans refléter une variation de masse grasse.</div></div>${bottom('progress')}</div>`}
function chartPoints(vals){if(!vals.length)return[];const min=Math.min(...vals.map(v=>v.value))-.8,max=Math.max(...vals.map(v=>v.value))+.8;return vals.map((v,i)=>({x:20+i*(300/Math.max(1,vals.length-1)),y:155-(v.value-min)/(max-min)*125}))}

function premium(){const p=config.prices;return `<div class="mobile-app"><div class="app-head"><div class="app-head-row"><button class="icon-btn" data-go="${state.onboarding?'app':'home'}">←</button>${logo()}<button class="link-btn" data-go="access">Déjà acheté</button></div></div><div class="screen"><div class="premium-hero"><div class="crown">✦</div><span class="tag">${esc(config.brand.toUpperCase())} PREMIUM</span><h1>Moins de calcul.<br>Plus de décisions.</h1><p class="screen-sub">${config.trialDays>0?`${config.trialDays} jours d’essai selon l’offre configurée dans Hotmart. `:''}L’abonnement et le prix final sont confirmés sur le checkout.</p></div><div class="benefits">${['Analyses photo et texte','Fourchette d’incertitude + portions modifiables','Composer le prochain repas selon ce qu’il reste','Coach contextualisé à votre journée','Code-barres, favoris et routines','Hydratation, poids, tour de taille et tendances','Badges et suivi de régularité','PWA installable sur l’écran d’accueil'].map(x=>`<div class="benefit"><span class="check">✓</span><b>${x}</b></div>`).join('')}</div><div class="plans"><button class="plan ${selectedPlan==='monthly'?'selected':''}" data-plan="monthly"><div class="plan-row"><div><b>Mensuel</b><div class="fine">Flexibilité maximale</div></div><span class="price">${esc(p.monthly)} €</span></div></button><button class="plan ${selectedPlan==='quarterly'?'selected':''}" data-plan="quarterly"><span class="badge">PLUS POPULAIRE</span><div class="plan-row"><div><b>3 mois</b><div class="fine">Le choix recommandé pour commencer</div></div><span class="price">${esc(p.quarterly)} €</span></div></button><button class="plan ${selectedPlan==='yearly'?'selected':''}" data-plan="yearly"><span class="badge">MEILLEURE VALEUR</span><div class="plan-row"><div><b>Annuel</b><div class="save">Prix d’ancrage modifiable dans .env</div></div><span class="price">${esc(p.yearly)} €</span></div></button></div><button class="btn btn-lime btn-wide" style="margin-top:12px" data-checkout>Continuer vers le paiement sécurisé →</button><p class="fine" style="text-align:center;margin-top:10px">Le paiement est traité sur votre checkout Hotmart. La disponibilité d’un essai, la récurrence, les taxes et les moyens de paiement doivent correspondre à votre configuration réelle Hotmart.</p><div class="legal-links"><button class="link-btn" data-go="legal">Conditions & confidentialité</button><button class="link-btn" data-go="access">Activer un achat</button></div></div></div>`}
function access(){return `<div class="mobile-app"><div class="app-head"><div class="app-head-row"><button class="icon-btn" data-go="home">←</button>${logo()}<span></span></div></div><div class="screen"><h1 class="screen-title">Activer mon accès</h1><p class="screen-sub">Utilisez la même adresse e-mail que lors de votre achat Hotmart.</p><div class="access-card"><div class="field"><label>E-mail d’achat</label><input id="access-email" type="email" placeholder="vous@exemple.fr" value="${esc(state.premiumEmail||'')}"></div><button class="btn btn-primary btn-wide" style="margin-top:10px" data-request-code>Recevoir mon code</button><div id="code-area" style="display:none"><div class="field"><label>Code à 6 chiffres</label><input id="access-code" class="code-input" inputmode="numeric" maxlength="6" placeholder="000000"></div><button class="btn btn-lime btn-wide" style="margin-top:10px" data-verify-code>Activer Premium</button></div><div id="access-msg"></div></div><div class="warn"><b>Pour le lancement :</b><br>Hotmart doit envoyer ses événements d’achat au webhook de l’application. Les noms exacts d’événements et la signature dépendent de votre compte Hotmart et sont configurés dans <code>.env</code>.</div></div></div>`}
function settings(){return `<div class="mobile-app"><div class="app-head"><div class="app-head-row"><button class="icon-btn" data-go="app">←</button><h2>Réglages</h2><span></span></div></div><div class="screen"><div class="kpi"><small>Votre objectif quotidien actuel</small><b>${fmt(state.profile.dailyKcal)} kcal</b><div class="fine">P ${state.profile.protein} g • G ${state.profile.carbs} g • L ${state.profile.fat} g • Fibres ${state.profile.fiber} g</div></div><div class="section-label"><h3>Compte</h3></div><div class="access-card">${state.premium?`<div class="success warn"><b>Premium actif ✓</b><br>${esc(state.premiumEmail||'Accès activé sur cet appareil.')}</div>`:`<button class="btn btn-lime btn-wide" data-go="premium">Passer Premium</button>`}${config.manageSubscriptionUrl?`<a class="btn btn-ghost btn-wide" style="margin-top:8px;text-decoration:none" href="${esc(config.manageSubscriptionUrl)}" target="_blank" rel="noopener">Gérer mon abonnement</a>`:''}</div><div class="section-label"><h3>Données & appareil</h3></div><button class="btn btn-ghost btn-wide" data-export>Exporter mes données (.json)</button><button class="btn btn-ghost btn-wide" style="margin-top:8px" data-install>Installer l’application</button><button class="btn btn-ghost btn-wide" style="margin-top:8px" data-go="legal">Conditions, confidentialité, mentions</button><button class="btn btn-ghost btn-wide" style="margin-top:8px;color:var(--danger)" data-reset>Effacer les données locales</button><div class="warn"><b>Stockage local dans cette version.</b><br>Les repas et mesures restent sur cet appareil. Pour une synchronisation multi-appareils, ajoutez une base + authentification avant une mise à l’échelle importante.</div></div></div>`}
function legal(){const l=config.legal||{};return `<div class="mobile-app"><div class="app-head"><div class="app-head-row"><button class="icon-btn" data-go="settings">←</button><h2>Informations légales</h2><span></span></div></div><div class="screen"><h1 class="screen-title">Transparence</h1><div class="day-card"><h3>Nature du service</h3><p class="screen-sub">${esc(config.brand)} est un outil général de suivi nutritionnel et de bien-être. Les calories, portions et macros sont des estimations et ne constituent pas un diagnostic, un traitement ou une prescription médicale.</p></div><div class="day-card"><h3>Abonnement</h3><p class="screen-sub">Le prix, la durée, un éventuel essai, le renouvellement automatique, les conditions d’annulation et les taxes doivent être affichés clairement sur votre checkout Hotmart avant confirmation de la commande.</p></div><div class="day-card"><h3>Droit de rétractation / contenu numérique</h3><p class="screen-sub">La configuration juridique finale doit être revue pour votre entité, votre statut fiscal et la manière dont l’accès au service numérique commence. N’utilisez pas ce texte comme avis juridique.</p></div><div class="day-card"><h3>Données</h3><p class="screen-sub">Cette version conserve principalement le journal nutritionnel dans le navigateur. Les photos envoyées pour analyse transitent par le serveur configuré. Documentez précisément vos sous-traitants, durées de conservation, base légale, droits d’accès/suppression et éventuels transferts hors EEE avant le lancement public.</p></div><div class="day-card"><h3>Éditeur — à compléter avant vente</h3><p class="screen-sub"><b>${esc(l.company||'VOTRE SOCIÉTÉ')}</b><br>${esc(l.address||'ADRESSE À COMPLÉTER')}<br>${esc(l.id||'IDENTIFIANT À COMPLÉTER')}<br>Support : ${esc(config.supportEmail)}</p></div><div class="warn"><b>À ne pas publier tel quel :</b><br>Complétez l’identité de l’éditeur et faites valider CGV/CGU, confidentialité, cookies/analytics, TVA et droit de la consommation applicables à votre structure et à la France.</div></div></div>`}

function render(){document.querySelector('.modal-wrap')?.remove();let html;if(route==='home')html=home();else if(route==='onboarding')html=onboarding();else if(route==='plan')html=planScreen();else if(route==='app')html=dashboard();else if(route==='planner')html=planner();else if(route==='coach')html=coach();else if(route==='insights')html=insights();else if(route==='progress')html=progress();else if(route==='premium')html=premium();else if(route==='access')html=access();else if(route==='settings')html=settings();else if(route==='legal')html=legal();else html=state.onboarding?dashboard():home();app.innerHTML=html;bind()}
function bind(){app.onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go){nav(b.dataset.go);return}if(b.dataset.start!==undefined){ob={step:0,data:{...state.profile}};track('StartQuiz');nav('onboarding');return}if(b.dataset.obValue!==undefined){const s=obSteps[ob.step];let v=b.dataset.obValue;if(s.key==='activity'||s.key==='speed'||s.key==='mealsPerDay')v=Number(v);ob.data[s.key]=v;render();return}if(b.dataset.obBack!==undefined){ob.step=Math.max(0,ob.step-1);render();return}if(b.dataset.obNext!==undefined){const s=obSteps[ob.step],field=$('#ob-field');if(field){let v=field.value.trim();if(s.type==='number')v=Number(v);if(v===''||Number.isNaN(v))return toast('Complétez cette étape.');if(s.min&&v<s.min||s.max&&v>s.max)return toast(`Valeur attendue entre ${s.min} et ${s.max}.`);ob.data[s.key]=v}if(ob.data[s.key]===undefined||ob.data[s.key]==='')return toast('Choisissez une option.');if(ob.step<obSteps.length-1){ob.step++;render()}else{track('CompleteQuiz');nav('plan')}return}if(b.dataset.activate!==undefined){state.profile=calcPlan();if(state.profile.warning&&Number(state.profile.age)<18)return toast('Cette version est réservée aux adultes.');state.onboarding=true;if(!state.weights.length)state.weights=[{day:todayKey(),value:Number(state.profile.weight)}];save();nav('app');return}if(b.dataset.openAdd!==undefined){openAdd('photo');return}if(b.dataset.addTab){openAdd(b.dataset.addTab);return}if(b.dataset.water){const k=todayKey();state.water[k]=Number(state.water[k]||0)+Number(b.dataset.water);save();render();return}if(b.dataset.meal){const m=state.meals.find(x=>String(x.id)===String(b.dataset.meal));if(m){modal={type:'meal',meal:m};renderModal()}return}if(b.dataset.compose!==undefined){await doCompose(b);return}if(b.dataset.addSuggestion){const s=JSON.parse(b.dataset.addSuggestion);state.meals.push({id:Date.now(),day:todayKey(),title:s.name,foods:(s.ingredients||[]).map(x=>({name:x,grams:0,kcal:0})),total:{kcal:s.kcal,protein:s.protein,carbs:s.carbs,fat:s.fat||0,fiber:s.fiber||0},icon:'✨'});save();track('MealSaved',{source:'planner'});toast('Repas ajouté ✓');render();return}if(b.dataset.coachSend!==undefined){await sendCoach();return}if(b.dataset.saveProgress!==undefined){const v=Number($('#weight-now').value),w=Number($('#waist-now').value||0);if(!v||v<30||v>300)return toast('Poids invalide.');state.profile.weight=v;state.weights.push({day:todayKey(),value:v});if(w>=40&&w<=200)state.waist.push({day:todayKey(),value:w});save();render();toast('Progression enregistrée');return}if(b.dataset.plan){selectedPlan=b.dataset.plan;render();return}if(b.dataset.checkout!==undefined){if(!config.checkoutConfigured?.[selectedPlan])return toast('Collez d’abord l’URL de checkout Hotmart dans .env.');track('BeginCheckout',{plan:selectedPlan});b.disabled=true;b.textContent='Ouverture du checkout…';try{const r=await fetch('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({plan:selectedPlan,...state.utms})}),d=await r.json();if(!r.ok)throw new Error(d.error);location.href=d.url}catch(err){toast(err.message);b.disabled=false;b.textContent='Continuer vers le paiement sécurisé →'}return}if(b.dataset.requestCode!==undefined){await requestCode();return}if(b.dataset.verifyCode!==undefined){await verifyCode();return}if(b.dataset.export!==undefined){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nutripilot-donnees.json';a.click();URL.revokeObjectURL(a.href);return}if(b.dataset.install!==undefined){if(window.deferredInstall){window.deferredInstall.prompt();await window.deferredInstall.userChoice}else toast('Utilisez « Ajouter à l’écran d’accueil » dans votre navigateur.');return}if(b.dataset.reset!==undefined){if(confirm('Effacer toutes les données locales ?')){localStorage.removeItem('nutripilot_v3');state=structuredClone(defaultState);location.hash='home';render()}return}}
 const ci=$('#coach-input');if(ci)ci.onkeydown=e=>{if(e.key==='Enter')$('[data-coach-send]')?.click()}
}
async function requestCode(){const email=$('#access-email').value.trim().toLowerCase(),msg=$('#access-msg');msg.innerHTML='<div class="fine" style="margin-top:10px">Vérification…</div>';try{const r=await fetch('/api/access/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})}),d=await r.json();if(!r.ok)throw new Error(d.error);state.premiumEmail=email;save();$('#code-area').style.display='block';msg.innerHTML=`<div class="warn success"><b>Code envoyé.</b><br>${d.mailed?'Consultez votre boîte e-mail.':'Le service d’e-mail n’est pas encore configuré.'}${d.devCode?` Code de développement : <b>${d.devCode}</b>`:''}</div>`}catch(e){msg.innerHTML=`<div class="warn">${esc(e.message)}</div>`}}
async function verifyCode(){const email=$('#access-email').value.trim().toLowerCase(),code=$('#access-code').value.trim();try{const r=await fetch('/api/access/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,code})}),d=await r.json();if(!r.ok)throw new Error(d.error);state.premium=true;state.premiumEmail=email;state.accessToken=d.token||'';save();track('PremiumActivated');toast('Premium activé ✓');nav('app')}catch(e){toast(e.message)}}
function bindModal(root){root.onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.close!==undefined){modal=null;root.remove();return}if(b.dataset.mtab){modal.tab=b.dataset.mtab;renderModal();return}if(b.dataset.analyzeText!==undefined){const text=$('#meal-text',root).value.trim();if(!text)return toast('Décrivez le repas.');await analyze({text,mode:'meal'});return}if(b.dataset.barcode!==undefined){const code=$('#barcode',root).value.trim();if(!code)return toast('Entrez le code-barres.');modal.loading=true;renderModal();try{const r=await fetch('/api/barcode?code='+encodeURIComponent(code)),d=await r.json();if(!r.ok)throw new Error(d.error);modal.loading=false;modal.result=d;renderModal()}catch(err){modal.loading=false;modal.result=null;renderModal();toast(err.message)}return}if(b.dataset.voice!==undefined){voiceInput(b,root);return}if(b.dataset.manual){const f=JSON.parse(b.dataset.manual),g=100,food={name:f[0],grams:g,kcal:f[1],protein:f[2],carbs:f[3],fat:f[4],fiber:f[5],confidence:.98};modal.result={title:f[0],foods:[food],total:{kcal:f[1],protein:f[2],carbs:f[3],fat:f[4],fiber:f[5]},confidence:.98,range:{min:Math.round(f[1]*.98),max:Math.round(f[1]*1.02)},assumptions:['Valeurs indicatives pour 100 g.'],note:'Ajustez la quantité réellement consommée.',source:'manual'};renderModal();return}if(b.dataset.fav!==undefined){const f=structuredClone(state.favorites[Number(b.dataset.fav)]);modal.result=f;renderModal();return}if(b.dataset.saveFavorite!==undefined){if(!modal.result)return;state.favorites.unshift(structuredClone(modal.result));state.favorites=state.favorites.slice(0,30);save();toast('Ajouté aux favoris ♡');return}if(b.dataset.saveResult!==undefined){recalcResult(root);const r=modal.result;state.meals.push({id:Date.now(),day:todayKey(),title:r.title||'Repas',foods:structuredClone(r.foods),total:structuredClone(r.total),icon:r.source==='openfoodfacts'?'▤':r.source==='manual'?'✍️':'📸'});state.trialScans+=r.source==='ai'||r.source==='fallback'?1:0;save();track('MealSaved',{source:r.source||'unknown',kcal:r.total.kcal});modal=null;root.remove();render();toast('Repas ajouté ✓');return}if(b.dataset.deleteMeal){state.meals=state.meals.filter(m=>String(m.id)!==String(b.dataset.deleteMeal));save();modal=null;root.remove();render();toast('Repas supprimé');return}}
 root.oninput=e=>{if(e.target.matches('[data-grams]'))recalcResult(root);if(e.target.id==='manual-search')$('#manual-list',root).innerHTML=manualResults(e.target.value)}
 const file=$('#meal-image',root);if(file)file.onchange=async()=>{const f=file.files?.[0];if(!f)return;if(f.size>7_000_000)return toast('Image trop lourde (7 Mo max).');const image=await fileToData(f,1600,.82);await analyze({image,mode:modal.tab==='label'?'label':'meal'})};if(modal.tab==='manual')$('#manual-list',root).innerHTML=manualResults('')
}
async function analyze(body){modal.loading=true;renderModal();try{const r=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw new Error(d.error);modal.loading=false;modal.result=d;renderModal();track('MealAnalyzed',{source:d.source||'unknown'})}catch(e){modal.loading=false;renderModal();toast(e.message)}}
function fileToData(file,max=1600,quality=.82){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',quality))};img.onerror=reject;img.src=url})}
function voiceInput(btn,root){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('Dictée vocale indisponible sur ce navigateur.');const rec=new SR();rec.lang='fr-FR';rec.interimResults=false;btn.classList.add('active');btn.textContent='● Écoute…';rec.onresult=e=>{$('#meal-text',root).value=(e.results[0][0].transcript||'')};rec.onerror=()=>toast('Impossible d’utiliser le micro.');rec.onend=()=>{btn.classList.remove('active');btn.textContent='🎙 Dicter'};rec.start()}

init();
